c:script.c:code:
// Sin default: una sede que no este en el diccionario NO se convierte en LIMA (antes
// getOrDefault(v,'LIMA') la inventaba: 31 alumnos de 'Sede ISTAT' quedaban en Lima).
def v = (input ?: '').toString().trim()
if (!v) return null
def r = ['Sede Lima':'LIMA','Filial Tarapoto':'TARAPOTO','Filial Juliaca':'JULIACA'].get(v)
if (r == null) log.warn('primary-sede-to-campusStudent: sede no reconocida "{}" -> sin valor (no se inventa)', v)
return r

// GATE de despliegue escalonado (2026-10-14, campus/escuela por matricula de PREGRADO vigente).
// Logica NUEVA (atributos PRIMARY_*) activa SOLO en: (a) simulaciones (modo de ejecucion no
// persistente) y (b) los canarios listados. En produccion, para el resto, sigue la logica vieja.
// Se retira en el corte masivo (ver docs/runbooks/estudiantes-campus-matricula-pregrado-2026-10-14).
// Ante cualquier error -> false (comportamiento de produccion de siempre).
def canarios = ['202512090', '202310412', '201612129'] as Set
def nuevo = false
try {
    def cod = basic.getAttributeValue(shadow, 'CODIGO')?.toString()?.trim()
    if (cod != null && canarios.contains(cod)) {
        nuevo = true
    } else {
        def m = midpoint.getCurrentTask()?.getExecutionMode()
        nuevo = (m != null && !m.isFullyPersistent())
    }
} catch (Exception ex) {
    nuevo = false
}
return nuevo

